function order(item, qty = 1, ...notes) {
  order.total += qty;

  return notes.length;
}

order.total = 0;

const again = order;

again("tea", 3);
again("jam");

console.log(again.name);
console.log(again.length);
console.log(order.total);
console.log(again("rice", 2, "fragile", "gift"));
